// motion-templates.js — Pleading paper template management
//
// Attorney uploads a .docx pleading paper template with special placeholders:
//   {{CONTENT}}        — motion body (paragraphs generated by Claude)
//   {{TITLE}}          — motion title (e.g. "MOTION FOR CONTINUANCE")
//   {{CLIENT_NAME}}    — client name
//   {{A_NUMBER}}       — A-number
//   {{COURT_NAME}}     — court name
//   {{JUDGE_NAME}}     — judge name
//   {{CASE_NUMBER}}    — case number (if provided)
//   {{DATE}}           — current date (MM/DD/YYYY)
//   {{FILING_DEADLINE}} — filing deadline if set
//
// On motion download/upload, we:
//   1. Load template DOCX (it's a ZIP with XML inside)
//   2. Extract document.xml
//   3. Replace all placeholders with actual values
//   4. For {{CONTENT}}, convert markdown to Word XML and inject
//   5. Repack the ZIP → return new .docx
//
// TIP FOR USERS: When typing placeholders in Word, type them as one
// continuous unit (don't apply bold/italic mid-placeholder, don't let Word
// auto-correct them). If Word underlines them as misspelled, right-click →
// "Add to dictionary" or "Ignore All" to prevent it from splitting the text
// across multiple XML runs.

const db = require("./db");
const PizZip = require("pizzip");

const brand = { gold: "#B79C62", navy: "#0C1C36" };

const KNOWN_PLACEHOLDERS = [
  "CONTENT", "TITLE", "CLIENT_NAME", "A_NUMBER", "COURT_NAME", "JUDGE_NAME",
  "CASE_NUMBER", "DATE", "FILING_DEADLINE",
];

// ─── Schema ──────────────────────────────────────────

async function init() {
  await db.query(`
    CREATE TABLE IF NOT EXISTS motion_templates (
      id                SERIAL PRIMARY KEY,
      name              TEXT NOT NULL,
      description       TEXT,
      is_default        BOOLEAN DEFAULT false,
      motion_types      JSONB DEFAULT '[]'::jsonb,
      docx_content      BYTEA NOT NULL,
      placeholders_found JSONB DEFAULT '[]'::jsonb,
      file_size_bytes   INTEGER,
      original_filename TEXT,
      uploaded_by       INTEGER,
      created_at        TIMESTAMP DEFAULT NOW(),
      updated_at        TIMESTAMP DEFAULT NOW()
    )
  `);
  await db.query(`CREATE INDEX IF NOT EXISTS idx_motion_templates_default ON motion_templates(is_default) WHERE is_default = true`);
  console.log("[motion-templates] Schema initialized");
}

// ─── Placeholder detection ───────────────────────────

// Scan the template's document.xml for placeholders. Word may split text
// across multiple runs, so we normalize by extracting just the visible text.
function detectPlaceholders(docxBuffer) {
  try {
    const zip = new PizZip(docxBuffer);
    const docXml = zip.file("word/document.xml")?.asText() || "";
    // Extract text between <w:t> tags, then normalize
    const textNodes = [...docXml.matchAll(/<w:t[^>]*>([^<]*)<\/w:t>/g)].map(m => m[1]);
    const fullText = textNodes.join("");
    // Find {{PLACEHOLDER}} patterns
    const found = new Set();
    const re = /\{\{\s*([A-Z_]+)\s*\}\}/g;
    let match;
    while ((match = re.exec(fullText)) !== null) {
      found.add(match[1].toUpperCase());
    }
    // Also check if placeholders got split across runs (partial detection)
    const partialMatches = [];
    for (const ph of KNOWN_PLACEHOLDERS) {
      // Check if the placeholder text appears in the raw XML (may be split by tags)
      // We do a fuzzy check by looking for the placeholder name with any XML content between chars
      const fuzzyRe = new RegExp(`\\{\\s*\\{[^}]*${ph.replace(/_/g, "._?")}[^{]*\\}\\s*\\}`, "s");
      if (!found.has(ph) && fuzzyRe.test(fullText)) {
        partialMatches.push(ph);
      }
    }
    return {
      detected: Array.from(found),
      possibly_split: partialMatches,
    };
  } catch (e) {
    console.warn("[motion-templates] placeholder detection failed:", e.message);
    return { detected: [], possibly_split: [], error: e.message };
  }
}

// ─── Template CRUD ───────────────────────────────────

async function uploadTemplate({ name, description, docxBuffer, filename, motionTypes, isDefault, userId }) {
  if (!docxBuffer || !docxBuffer.length) throw new Error("No file uploaded");
  // Validate it's actually a DOCX (ZIP starting with PK)
  if (docxBuffer[0] !== 0x50 || docxBuffer[1] !== 0x4B) {
    throw new Error("File is not a valid .docx — must be a Word document");
  }
  // Validate it has document.xml inside
  try {
    const zip = new PizZip(docxBuffer);
    if (!zip.file("word/document.xml")) {
      throw new Error("File is not a valid .docx — missing word/document.xml");
    }
  } catch (e) {
    throw new Error(`Invalid .docx: ${e.message}`);
  }

  const placeholders = detectPlaceholders(docxBuffer);

  // If setting as default, unset previous default
  if (isDefault) {
    await db.query(`UPDATE motion_templates SET is_default = false, updated_at = NOW() WHERE is_default = true`);
  }

  const { rows } = await db.query(
    `INSERT INTO motion_templates
      (name, description, is_default, motion_types, docx_content, placeholders_found,
       file_size_bytes, original_filename, uploaded_by)
     VALUES ($1, $2, $3, $4::jsonb, $5, $6::jsonb, $7, $8, $9)
     RETURNING id`,
    [
      name || filename || "Untitled template",
      description || null,
      !!isDefault,
      JSON.stringify(motionTypes || []),
      docxBuffer,
      JSON.stringify(placeholders),
      docxBuffer.length,
      filename || null,
      userId || null,
    ]
  );
  return { id: rows[0].id, placeholders };
}

async function listTemplates() {
  const { rows } = await db.query(
    `SELECT id, name, description, is_default, motion_types, placeholders_found,
            file_size_bytes, original_filename, created_at, updated_at
     FROM motion_templates
     ORDER BY is_default DESC, created_at DESC`
  );
  return rows;
}

async function getTemplate(id) {
  const { rows } = await db.query(`SELECT * FROM motion_templates WHERE id = $1`, [id]);
  return rows[0] || null;
}

// Get the best template for a specific motion type.
// Priority: (1) a template that lists this motion_type in its motion_types
// array, (2) the default template, (3) any template.
async function getTemplateForMotion(motionType) {
  // Try specific-type template first
  const specificRes = await db.query(
    `SELECT * FROM motion_templates
     WHERE motion_types::jsonb ? $1
     ORDER BY is_default DESC, updated_at DESC
     LIMIT 1`,
    [motionType]
  );
  if (specificRes.rows[0]) return specificRes.rows[0];
  // Fall back to default
  const defaultRes = await db.query(
    `SELECT * FROM motion_templates WHERE is_default = true LIMIT 1`
  );
  if (defaultRes.rows[0]) return defaultRes.rows[0];
  return null;
}

async function deleteTemplate(id) {
  await db.query(`DELETE FROM motion_templates WHERE id = $1`, [id]);
}

async function setDefault(id) {
  await db.query(`UPDATE motion_templates SET is_default = false, updated_at = NOW() WHERE is_default = true`);
  await db.query(`UPDATE motion_templates SET is_default = true, updated_at = NOW() WHERE id = $1`, [id]);
}

// ─── Apply template — substitute placeholders + inject content ────

// Apply the template to generate a final DOCX. Substitutes simple placeholders
// like {{CLIENT_NAME}} and injects markdown body at {{CONTENT}}.
function applyTemplate(templateBuffer, values) {
  const zip = new PizZip(templateBuffer);
  const docXmlFile = zip.file("word/document.xml");
  if (!docXmlFile) throw new Error("Template missing word/document.xml");
  let docXml = docXmlFile.asText();

  // ── Phase 1: Handle simple text placeholders ─────────────
  // Word often splits text across multiple <w:t> tags. To handle this reliably,
  // we do two passes:
  //   (a) Direct substitution in the raw XML (works if placeholder is intact)
  //   (b) A normalized pass that merges adjacent runs before substituting

  const simpleReplacements = {
    "TITLE":           values.title || "",
    "CLIENT_NAME":     values.client_name || "",
    "A_NUMBER":        values.a_number || "",
    "COURT_NAME":      values.court_name || "",
    "JUDGE_NAME":      values.judge_name || "",
    "CASE_NUMBER":     values.case_number || "",
    "DATE":            values.date || new Date().toLocaleDateString("en-US"),
    "FILING_DEADLINE": values.filing_deadline || "",
  };

  // Direct substitution — {{PLACEHOLDER}} appearing intact in one run
  for (const [key, val] of Object.entries(simpleReplacements)) {
    const escaped = escapeXml(String(val));
    const re = new RegExp(`\\{\\{\\s*${key}\\s*\\}\\}`, "g");
    docXml = docXml.replace(re, escaped);
  }

  // Fallback: if placeholders got split by Word across runs, try normalizing
  // Look for run pairs where {{ is in one run and }} is in another with the
  // placeholder name in between. We consolidate then substitute.
  docXml = fixSplitPlaceholders(docXml, simpleReplacements);

  // ── Phase 2: Handle {{CONTENT}} — inject markdown as paragraphs ──
  if (values.content_markdown) {
    docXml = injectContent(docXml, values.content_markdown);
  }

  // Write back
  zip.file("word/document.xml", docXml);
  return zip.generate({ type: "nodebuffer", compression: "DEFLATE" });
}

// If Word split "{{CLIENT_NAME}}" across multiple <w:t> runs, try to fix.
// We look for text where the marker appears when tags are stripped and rebuild.
function fixSplitPlaceholders(xml, replacements) {
  // Find each paragraph and check if any placeholder appears when tags stripped
  // Split by paragraphs to limit scope
  const paragraphs = xml.split(/(<\/w:p>)/);
  for (let i = 0; i < paragraphs.length; i += 2) {
    const p = paragraphs[i];
    // Extract visible text
    const visibleText = p.replace(/<[^>]+>/g, "");
    for (const [key, val] of Object.entries(replacements)) {
      const marker = `{{${key}}}`;
      const markerSpaced = `{{ ${key} }}`;
      const found = visibleText.includes(marker) || visibleText.includes(markerSpaced);
      if (found && !p.includes(`{{${key}}}`) && !p.includes(`{{ ${key} }}`)) {
        // Placeholder is split across runs. Replace the entire paragraph's
        // text content with the value. This is imperfect (loses fine-grained
        // formatting inside the paragraph) but preserves the paragraph structure.
        const firstRun = p.match(/(<w:r[^>]*>[\s\S]*?)<w:t[^>]*>/);
        if (firstRun) {
          // Extract everything up to first <w:t>, then insert value, close <w:t>,
          // then close remaining tags
          const rPr = p.match(/<w:rPr>[\s\S]*?<\/w:rPr>/)?.[0] || "";
          const pPr = p.match(/<w:pPr>[\s\S]*?<\/w:pPr>/)?.[0] || "";
          paragraphs[i] = `<w:p>${pPr}<w:r>${rPr}<w:t xml:space="preserve">${escapeXml(val)}</w:t></w:r>`;
        }
      }
    }
  }
  return paragraphs.join("");
}

// Convert markdown to Word XML paragraphs and replace {{CONTENT}} placeholder.
function injectContent(xml, markdown) {
  const paragraphsXml = markdownToWordParagraphs(markdown);
  // Find the paragraph containing {{CONTENT}} and replace it entirely with generated paragraphs
  // Match: <w:p ...>...{{CONTENT}}...</w:p>
  const contentRe = /<w:p[^>]*>[\s\S]*?\{\{\s*CONTENT\s*\}\}[\s\S]*?<\/w:p>/;
  if (contentRe.test(xml)) {
    return xml.replace(contentRe, paragraphsXml);
  }
  // Also handle split placeholder case: find paragraph whose stripped text contains {{CONTENT}}
  const paras = xml.split(/(<\/w:p>)/);
  for (let i = 0; i < paras.length; i += 2) {
    const visibleText = paras[i].replace(/<[^>]+>/g, "");
    if (visibleText.includes("{{CONTENT}}") || visibleText.includes("{{ CONTENT }}")) {
      paras[i] = paragraphsXml.replace(/<\/w:p>$/, "");  // strip closing tag - the split() rejoin will add it
      // Actually just replace with generated content and skip closing tag rejoin
      paras[i] = paragraphsXml;
      paras[i + 1] = "";
      break;
    }
  }
  return paras.join("");
}

function markdownToWordParagraphs(md) {
  const lines = md.split(/\r?\n/);
  const paragraphs = [];
  for (const rawLine of lines) {
    const line = rawLine.trim();
    if (!line) {
      paragraphs.push(`<w:p/>`);
      continue;
    }
    if (/^##\s+/.test(line)) {
      const text = escapeXml(line.replace(/^##\s+/, ""));
      paragraphs.push(`<w:p><w:pPr><w:spacing w:before="240" w:after="120"/></w:pPr><w:r><w:rPr><w:b/><w:sz w:val="26"/></w:rPr><w:t xml:space="preserve">${text}</w:t></w:r></w:p>`);
      continue;
    }
    if (/^#\s+/.test(line)) {
      const text = escapeXml(line.replace(/^#\s+/, ""));
      paragraphs.push(`<w:p><w:pPr><w:jc w:val="center"/><w:spacing w:before="240" w:after="240"/></w:pPr><w:r><w:rPr><w:b/><w:sz w:val="28"/></w:rPr><w:t xml:space="preserve">${text}</w:t></w:r></w:p>`);
      continue;
    }
    // Normal paragraph with inline **bold** and *italic*
    const runs = renderInlineRuns(line);
    paragraphs.push(`<w:p><w:pPr><w:jc w:val="both"/></w:pPr>${runs}</w:p>`);
  }
  return paragraphs.join("");
}

function renderInlineRuns(text) {
  const runs = [];
  let remaining = text;
  const BOLD = /\*\*(.+?)\*\*/;
  const ITALIC = /\*(.+?)\*/;
  while (remaining.length) {
    const boldMatch = remaining.match(BOLD);
    const italicMatch = remaining.match(ITALIC);
    let match = null;
    let type = null;
    if (boldMatch && (!italicMatch || boldMatch.index <= italicMatch.index)) {
      match = boldMatch; type = "bold";
    } else if (italicMatch) {
      match = italicMatch; type = "italic";
    }
    if (!match) {
      runs.push(makeRun(remaining));
      break;
    }
    if (match.index > 0) runs.push(makeRun(remaining.substring(0, match.index)));
    runs.push(makeRun(match[1], type));
    remaining = remaining.substring(match.index + match[0].length);
  }
  return runs.join("");
}

function makeRun(text, style = null) {
  const escapedText = escapeXml(text);
  const rPr = style === "bold" ? "<w:rPr><w:b/></w:rPr>"
            : style === "italic" ? "<w:rPr><w:i/></w:rPr>"
            : "";
  return `<w:r>${rPr}<w:t xml:space="preserve">${escapedText}</w:t></w:r>`;
}

function escapeXml(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

// ─── UI rendering ────────────────────────────────────

function escapeHtml(s) {
  return String(s || "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function renderTemplatesPage(templates, motionTypes) {
  const rows = templates.map(t => {
    const detected = t.placeholders_found?.detected || [];
    const missing = KNOWN_PLACEHOLDERS.filter(p => !detected.includes(p));
    const detectedHtml = detected.length
      ? detected.map(p => `<span style="background:#e8f5e9; color:#2e7d32; padding:2px 6px; border-radius:3px; font-size:10px; margin:1px;">{{${p}}}</span>`).join(" ")
      : '<span style="color:#c00; font-size:11px;">⚠️ No placeholders detected</span>';
    const missingHtml = missing.length
      ? '<div style="margin-top:6px; font-size:11px; color:#888;">Not used: ' + missing.map(p => `<span style="color:#aaa;">{{${p}}}</span>`).join(", ") + '</div>'
      : "";
    const typesForThis = t.motion_types || [];
    const typeLabels = typesForThis.length
      ? typesForThis.map(mt => (motionTypes[mt]?.short || mt)).join(", ")
      : "All motion types (default)";
    return `
      <div style="background:white; border:1px solid #e0e0e0; border-radius:8px; padding:16px; margin-bottom:12px;">
        <div style="display:flex; justify-content:space-between; align-items:flex-start;">
          <div>
            <div style="display:flex; align-items:center; gap:8px;">
              <h3 style="margin:0; color:${brand.navy};">${escapeHtml(t.name)}</h3>
              ${t.is_default ? '<span style="background:' + brand.gold + '; color:white; padding:3px 8px; border-radius:12px; font-size:10px; font-weight:600;">DEFAULT</span>' : ""}
            </div>
            <div style="font-size:12px; color:#666; margin-top:4px;">
              📎 ${escapeHtml(t.original_filename || "template.docx")} · ${(t.file_size_bytes / 1024).toFixed(1)} KB · Uploaded ${new Date(t.created_at).toLocaleDateString()}
            </div>
            <div style="font-size:12px; color:#666; margin-top:4px;">
              Used for: <b>${escapeHtml(typeLabels)}</b>
            </div>
            ${t.description ? `<div style="font-size:12px; color:#555; margin-top:6px; font-style:italic;">${escapeHtml(t.description)}</div>` : ""}
            <div style="margin-top:10px;">
              <div style="font-size:11px; color:#666; margin-bottom:4px;"><b>Placeholders found in template:</b></div>
              <div>${detectedHtml}</div>
              ${missingHtml}
            </div>
          </div>
          <div style="display:flex; flex-direction:column; gap:6px; align-items:flex-end;">
            <a href="/admin/motions/templates/${t.id}/download" style="background:#eee; color:#333; padding:6px 12px; border-radius:4px; text-decoration:none; font-size:11px;">💾 Download</a>
            ${!t.is_default ? `<button onclick="setDefault(${t.id})" style="background:${brand.gold}; color:white; border:none; padding:6px 12px; border-radius:4px; cursor:pointer; font-size:11px;">Set as default</button>` : ""}
            <button onclick="deleteTemplate(${t.id})" style="background:transparent; color:#c00; border:1px solid #ffe0e0; padding:6px 12px; border-radius:4px; cursor:pointer; font-size:11px;">🗑 Delete</button>
          </div>
        </div>
      </div>`;
  }).join("");

  const motionTypeCheckboxes = Object.entries(motionTypes).map(([key, cfg]) =>
    `<label style="display:inline-flex; align-items:center; margin-right:16px; margin-bottom:6px; font-weight:normal;"><input type="checkbox" name="motion_types" value="${key}" style="margin-right:4px;"> ${cfg.label}</label>`
  ).join("");

  return `
  <div class="page-header" style="display:flex; justify-content:space-between; align-items:flex-start; flex-wrap:wrap; gap:12px;">
    <div>
      <h1 style="margin:0;">📋 Motion Templates</h1>
      <div style="font-size:12px; color:#666; margin-top:4px;">Pleading paper templates that Claude uses when drafting motions.</div>
    </div>
    <a href="/admin/motions" class="back-link">← Back to motions</a>
  </div>

  <!-- Instructions box -->
  <div style="background:#fff8e1; border-left:4px solid ${brand.gold}; padding:14px 18px; border-radius:4px; margin:16px 0; font-size:13px; line-height:1.6;">
    <div style="font-weight:600; color:${brand.navy}; margin-bottom:6px;">📖 How to prepare your template</div>
    <p style="margin:0 0 8px 0;">Upload a .docx file with your firm's pleading paper (caption, line numbers, margins, signature block, etc.). Add these placeholders where content should appear:</p>
    <ul style="margin:0 0 8px 20px; padding:0;">
      <li><code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{CONTENT}}</code> — <b>required.</b> Where Claude's motion body goes (put on its own line, unformatted).</li>
      <li><code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{TITLE}}</code> — motion title (e.g. "MOTION FOR CONTINUANCE")</li>
      <li><code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{CLIENT_NAME}}</code>, <code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{A_NUMBER}}</code></li>
      <li><code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{COURT_NAME}}</code>, <code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{JUDGE_NAME}}</code></li>
      <li><code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{DATE}}</code>, <code style="background:#f0f0f0; padding:1px 5px; border-radius:3px;">{{FILING_DEADLINE}}</code></li>
    </ul>
    <p style="margin:0; font-size:12px; color:#666;">💡 <b>Tip:</b> Type placeholders without bold/italic in the middle of the text. If Word red-underlines them, right-click → "Add to dictionary" so Word doesn't split them across runs. After upload, we detect which placeholders you used and only fill those.</p>
  </div>

  <!-- Upload form -->
  <div style="background:white; border:1px solid #e0e0e0; border-radius:8px; padding:20px; margin-bottom:20px;">
    <h3 style="margin-top:0; color:${brand.navy};">📤 Upload new template</h3>
    <form id="upload-template-form" onsubmit="uploadTemplate(event)" enctype="multipart/form-data">
      <div style="margin-bottom:12px;">
        <label style="display:block; font-size:12px; color:#666; margin-bottom:4px;">Template file (.docx) *</label>
        <input type="file" name="template_file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" required style="width:100%; padding:8px; border:1px solid #ccc; border-radius:4px;">
      </div>
      <div style="margin-bottom:12px;">
        <label style="display:block; font-size:12px; color:#666; margin-bottom:4px;">Template name *</label>
        <input type="text" name="name" required placeholder="e.g. Immigration Pleading Paper — 28 lines" style="width:100%; padding:8px; border:1px solid #ccc; border-radius:4px; box-sizing:border-box;">
      </div>
      <div style="margin-bottom:12px;">
        <label style="display:block; font-size:12px; color:#666; margin-bottom:4px;">Description (optional)</label>
        <input type="text" name="description" placeholder="Notes about when/how to use this template" style="width:100%; padding:8px; border:1px solid #ccc; border-radius:4px; box-sizing:border-box;">
      </div>
      <div style="margin-bottom:12px;">
        <label style="display:block; font-size:12px; color:#666; margin-bottom:6px;">Use for which motion types? (leave all unchecked to apply to all)</label>
        <div>${motionTypeCheckboxes}</div>
      </div>
      <div style="margin-bottom:16px;">
        <label style="display:inline-flex; align-items:center; font-weight:normal;">
          <input type="checkbox" name="is_default" style="margin-right:6px;"> Set as default template (used for any motion without a specific template)
        </label>
      </div>
      <button type="submit" style="background:${brand.navy}; color:white; padding:10px 20px; border:none; border-radius:4px; cursor:pointer; font-weight:600;">📤 Upload template</button>
    </form>
  </div>

  <!-- Existing templates -->
  ${templates.length ? `<h3 style="color:${brand.navy};">Your templates (${templates.length})</h3>${rows}` : `<div style="text-align:center; padding:40px; color:#888; background:white; border-radius:8px; border:1px dashed #ccc;">No templates yet. Upload your first pleading paper above to get started.<br><br>Motions will still generate without a template — they'll just use plain formatting.</div>`}

  <script>
    async function uploadTemplate(e) {
      e.preventDefault();
      const form = e.target;
      const fd = new FormData();
      fd.append("template_file", form.template_file.files[0]);
      fd.append("name", form.name.value);
      fd.append("description", form.description.value || "");
      fd.append("is_default", form.is_default.checked ? "true" : "false");
      const types = Array.from(form.querySelectorAll('input[name="motion_types"]:checked')).map(el => el.value);
      fd.append("motion_types", JSON.stringify(types));

      const btn = form.querySelector('button[type="submit"]');
      btn.disabled = true;
      btn.textContent = "⏳ Uploading…";
      try {
        const r = await fetch("/admin/motions/templates", { method: "POST", body: fd });
        const d = await r.json();
        if (d.ok) {
          const found = d.template?.placeholders?.detected?.length || 0;
          alert("Template uploaded! Detected " + found + " placeholders. " + (found === 0 ? "⚠️ No placeholders found — Claude will still generate motions but they won't use the template. Make sure your Word doc has {{CONTENT}} typed in cleanly." : ""));
          location.reload();
        } else {
          alert("Upload failed: " + (d.error || "unknown"));
          btn.disabled = false;
          btn.textContent = "📤 Upload template";
        }
      } catch (err) {
        alert("Upload failed: " + err.message);
        btn.disabled = false;
        btn.textContent = "📤 Upload template";
      }
    }
    async function setDefault(id) {
      try {
        const r = await fetch("/admin/motions/templates/" + id + "/set-default", { method: "POST" });
        if ((await r.json()).ok) location.reload();
      } catch (e) { alert("Failed: " + e.message); }
    }
    async function deleteTemplate(id) {
      if (!confirm("Delete this template? Existing motions won't be affected.")) return;
      try {
        const r = await fetch("/admin/motions/templates/" + id, { method: "DELETE" });
        if ((await r.json()).ok) location.reload();
      } catch (e) { alert("Failed: " + e.message); }
    }
  </script>`;
}

module.exports = {
  init,
  uploadTemplate,
  listTemplates,
  getTemplate,
  getTemplateForMotion,
  deleteTemplate,
  setDefault,
  applyTemplate,
  detectPlaceholders,
  renderTemplatesPage,
  KNOWN_PLACEHOLDERS,
};
